{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Flupirtine, which shares an ethyl carbamate/ester motif, a fluorophenyl ring, and a heteroaromatic core with the query, has an absolute oral bioavailability of approximately 70% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Risperidone, a fused heterocyclic drug with a fluorophenyl substituent and amide-like features, has an absolute oral bioavailability of 70% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lemborexant, a fused heteroaromatic compound with fluorophenyl and amide functionality, has at least 87% oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Trovafloxacin, a fused heteroaromatic fluoroquinolone with fluorophenyl substitution, has an absolute oral bioavailability of 88% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A structurally more distant analogue with an NH donor, a basic piperazine side chain, and larger size showed only ~10% oral bioavailability in humans; this is the only affirmative low-F evidence, but its transferability to the query is limited because the query lacks these liabilities and has lower molecular weight and no hydrogen-bond donors.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's favorable physicochemical profile (low MW, no HBD, moderate logP, neutral at physiological pH) is reinforced by multiple human absolute-bioavailability analogues with similar structural motifs showing F ≥50%. The single low-F analogue is structurally dissimilar and its liabilities are absent in the query, so F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule.",
    "Morgan similarities to the evidence molecules are low (~0.23–0.26), making structural transfer approximate.",
    "Human metabolic stability of the ethyl ester and lactam groups is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

